package com.example.insightku.ui.components.analytics

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.insightku.ui.components.analytics.model.AnalyticsDataSource
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.launch
import javax.inject.Inject

@HiltViewModel
class AnalyticsViewModel @Inject constructor() : ViewModel() {

    var uiState by mutableStateOf(AnalyticsState())
        private set

    init {
        loadAnalytics()
    }

    fun onEvent(event: AnalyticsEvent) {
        when (event) {
            is AnalyticsEvent.LoadAnalytics -> loadAnalytics()
            is AnalyticsEvent.SelectMonth -> selectMonth(event.month)
            is AnalyticsEvent.ChangeTimePeriod -> changeTimePeriod(event.period)
            is AnalyticsEvent.ChangeBudgetPeriod -> changeBudgetPeriod(event.period)
            is AnalyticsEvent.SelectExpenseCategory -> selectExpenseCategory(event.categoryName)
            is AnalyticsEvent.SelectIncomeCategory -> selectIncomeCategory(event.categoryName)
            is AnalyticsEvent.NextMonth -> navigateToNextMonth()
            is AnalyticsEvent.PreviousMonth -> navigateToPreviousMonth()
            is AnalyticsEvent.ClearError -> clearError()
        }
    }

    private fun loadAnalytics() {
        viewModelScope.launch {
            try {
                uiState = uiState.copy(isLoading = true, error = null)

                val availableMonths = AnalyticsDataSource.monthlyData.keys.sortedDescending()
                val currentMonthData = AnalyticsDataSource.monthlyData[uiState.selectedMonth]

                if (currentMonthData != null) {
                    val savings = currentMonthData.totalIncome - currentMonthData.totalExpenses
                    val savingsRate = (savings / currentMonthData.totalIncome) * 100

                    val incomeExpenseData = if (uiState.timePeriod == TimePeriod.WEEKLY) {
                        AnalyticsDataSource.weeklyIncomeExpenseData
                    } else {
                        AnalyticsDataSource.monthlyIncomeExpenseData
                    }

                    val budgetData = if (uiState.budgetPeriod == TimePeriod.WEEKLY) {
                        AnalyticsDataSource.weeklyBudgetData
                    } else {
                        AnalyticsDataSource.monthlyBudgetData
                    }

                    uiState = uiState.copy(
                        isLoading = false,
                        availableMonths = availableMonths,
                        currentMonthData = currentMonthData,
                        savings = savings,
                        savingsRate = savingsRate,
                        incomeExpenseData = incomeExpenseData,
                        budgetData = budgetData,
                        incomeCategories = AnalyticsDataSource.incomeCategories
                    )
                } else {
                    uiState = uiState.copy(
                        isLoading = false,
                        error = "Data for selected month not found"
                    )
                }
            } catch (e: Exception) {
                uiState = uiState.copy(
                    isLoading = false,
                    error = e.message ?: "An error occurred while loading analytics"
                )
            }
        }
    }

    private fun selectMonth(month: String) {
        uiState = uiState.copy(selectedMonth = month)
        loadAnalytics()
    }

    private fun changeTimePeriod(period: TimePeriod) {
        uiState = uiState.copy(timePeriod = period)
        loadAnalytics() // Reload data for new period
    }

    private fun changeBudgetPeriod(period: TimePeriod) {
        uiState = uiState.copy(budgetPeriod = period)
        loadAnalytics() // Reload data for new budget period
    }

    private fun selectExpenseCategory(categoryName: String?) {
        uiState = uiState.copy(
            selectedExpenseCategory = if (uiState.selectedExpenseCategory == categoryName) null else categoryName
        )
    }

    private fun selectIncomeCategory(categoryName: String?) {
        uiState = uiState.copy(
            selectedIncomeCategory = if (uiState.selectedIncomeCategory == categoryName) null else categoryName
        )
    }

    private fun navigateToNextMonth() {
        val currentIndex = uiState.availableMonths.indexOf(uiState.selectedMonth)
        if (currentIndex > 0) {
            selectMonth(uiState.availableMonths[currentIndex - 1])
        }
    }

    private fun navigateToPreviousMonth() {
        val currentIndex = uiState.availableMonths.indexOf(uiState.selectedMonth)
        if (currentIndex < uiState.availableMonths.size - 1) {
            selectMonth(uiState.availableMonths[currentIndex + 1])
        }
    }

    private fun clearError() {
        uiState = uiState.copy(error = null)
    }

    // Helper functions for UI
    fun getMonthName(monthKey: String): String {
        return try {
            val date = java.time.LocalDate.parse("$monthKey-01")
            val formatter = java.time.format.DateTimeFormatter.ofPattern("MMMM yyyy")
            date.format(formatter)
        } catch (e: Exception) {
            monthKey
        }
    }

    fun formatCurrency(amount: Double): String {
        return "Rp ${String.format("%,.0f", amount)}"
    }

    fun canNavigateNext(): Boolean {
        val currentIndex = uiState.availableMonths.indexOf(uiState.selectedMonth)
        return currentIndex > 0
    }

    fun canNavigatePrevious(): Boolean {
        val currentIndex = uiState.availableMonths.indexOf(uiState.selectedMonth)
        return currentIndex < uiState.availableMonths.size - 1
    }
}
